import os
import re
import unicodedata
import hashlib
import hmac
import secrets
from urllib.parse import unquote, urlparse
from pathlib import PurePosixPath

# Configuration
DOCUMENT_ROOT = "/var/www/static"
SECRET_KEY = os.environ.get("HMAC_SECRET", secrets.token_hex(32))
ALLOWED_EXTENSIONS = {".html", ".css", ".js", ".png", ".jpg", ".gif", ".svg", ".woff2"}

class RequestContext:
    def __init__(self, method, path, headers, body=b""):
        self.method = method
        self.path = path
        self.headers = headers
        self.body = body
        self.user = None
        self.validated_path = None

def constant_time_compare(a: bytes, b: bytes) -> bool:
    return hmac.compare_digest(a, b)

def generate_token(user_id: str) -> str:
    return hmac.new(SECRET_KEY.encode(), user_id.encode(), hashlib.sha256).hexdigest()

def authenticate(ctx: RequestContext) -> bool:
    auth_header = ctx.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        return False
    token = auth_header[7:]
    user_id = ctx.headers.get("X-User-ID", "")
    if not user_id:
        return False
    expected = hmac.new(SECRET_KEY.encode(), user_id.encode(), hashlib.sha256).hexdigest()
    if constant_time_compare(token.encode(), expected.encode()):
        ctx.user = user_id
        return True
    return False

def decode_request_path(raw_path: str) -> str:
    """Decode URL-encoded path components."""
    decoded = unquote(raw_path)
    # Strip query string and fragment
    parsed = urlparse(decoded)
    return parsed.path

def check_path_safety(path: str) -> bool:
    """Verify path doesn't contain traversal sequences.
    This check runs on the decoded path BEFORE normalization."""
    # Block obvious traversal
    if ".." in path:
        return False
    if "\x00" in path:
        return False
    # Must start with /
    if not path.startswith("/"):
        return False
    # Check each component
    parts = path.split("/")
    for part in parts:
        if part in (".", ".."):
            return False
        # Block hidden files
        if part.startswith(".") and len(part) > 1:
            return False
    return True

def normalize_unicode(path: str) -> str:
    """Normalize Unicode characters in path for consistent handling.
    Uses NFKC to fold compatibility characters."""
    return unicodedata.normalize("NFKC", path)

def check_extension(path: str) -> bool:
    """Verify file extension is allowed."""
    ext = os.path.splitext(path)[1].lower()
    return ext in ALLOWED_EXTENSIONS

def resolve_file_path(validated_path: str) -> str:
    """Construct the final filesystem path."""
    # Join with document root
    full_path = os.path.join(DOCUMENT_ROOT, validated_path.lstrip("/"))
    return full_path

def validate_and_resolve(ctx: RequestContext) -> tuple:
    """Main validation pipeline for static file requests.
    Returns (success: bool, path_or_error: str)"""

    # Step 1: Decode the URL-encoded path
    decoded_path = decode_request_path(ctx.path)

    # Step 2: Security check on decoded path
    if not check_path_safety(decoded_path):
        return (False, "Path traversal detected")

    # Step 3: Normalize Unicode (NFKC normalization)
    # This handles compatibility decomposition for consistent lookups
    normalized_path = normalize_unicode(decoded_path)

    # Step 4: Check file extension
    if not check_extension(normalized_path):
        return (False, "File type not allowed")

    # Step 5: Resolve to filesystem path
    file_path = resolve_file_path(normalized_path)

    ctx.validated_path = file_path
    return (True, file_path)

def serve_static_file(ctx: RequestContext) -> dict:
    """Handle a static file request."""
    success, result = validate_and_resolve(ctx)

    if not success:
        return {"status": 403, "body": result}

    file_path = result

    # Check file exists
    if not os.path.isfile(file_path):
        return {"status": 404, "body": "Not found"}

    # Read and return file
    try:
        with open(file_path, "rb") as f:
            content = f.read()
        return {"status": 200, "body": content}
    except PermissionError:
        return {"status": 403, "body": "Access denied"}

def handle_request(method: str, path: str, headers: dict, body: bytes = b"") -> dict:
    """Main request handler."""
    ctx = RequestContext(method, path, headers, body)

    if method == "GET":
        return serve_static_file(ctx)

    # Protected endpoints require auth
    if not authenticate(ctx):
        return {"status": 401, "body": "Unauthorized"}

    if method == "POST" and ctx.validated_path:
        return {"status": 200, "body": "OK"}

    return {"status": 405, "body": "Method not allowed"}
